INTRO = "Inside a private dining room at a Korean restaurant, producer Ra Joon-mo and head writer Son Ji-yeon wait nervously for their cast dinner to begin. Veteran actress Youn Yuh-jung walks in beaming over a box of famous cake, completely unaware that the cast is leaving the show. Listen to the Korean first, then we'll go through it together."
OPENER = "Now let's go through it line by line with the English translation."
TRANSITION = "Now let's listen to the whole conversation one last time."
OUTRO = 'You heard Youn Yuh-jung arrive beaming with a box of famous cake while Joon-mo and Ji-yeon struggle to hide the truth at dinner. Until next time.'
CLOSING = ('joonmo', '다음에 만나요!')

STORY = [('writer', '아직 연락이 없는데요.', 'There is no word yet.', [(798, '아직 연락이 없는데요')], ''), ('writer', '다들 오실까요?', 'Will everyone come?', [(799, '다들 오실까요?')], ''), ('writer', '윤여정 선생님, 여기 앉으세요.', 'Ms. Youn Yuh-jung, please sit here.', [(809, '윤여정 선생님 여기 앉으세요')], ''), ('actress', '안녕하세요.', 'Hello.', [(828, '안녕하세요')], ''), ('joonmo', '선생님, 한 잔 받으시지.', 'Teacher, let me pour you a glass.', [(842, '선생님 한 잔 받으시지.')], ''), ('actress', '나 이 프로 라 피디 때문에 한 거야.', 'I took this show because of Producer Ra.', [(843, '나 이 프로 라피디 때문에 한 거야')], ''), ('joonmo', '그럼요, 알죠.', 'Of course, I know.', [(844, '그럼요 알죠.')], ''), ('writer', '선생님 여기 케이크 좋아한다고 하셔서요.', 'Because we heard you love the cake from this shop.', [(847, '선생님 여기 케이크 좋아한다고 하셔서요')], ''), ('actress', '점심때만 돼도 케이크 다 품절되는 집이잖아.', 'Even by lunchtime, this shop sells out of cake.', [(850, '점심때만 돼도 케이크 다 품절되는 집이잖아')], ''), ('joonmo', '선생님, 그동안 정말 수고 많으셨습니다.', 'Teacher, thank you so much for all your hard work up to now.', [(852, '선생님 그동안 정말 수고 많으셨습니다')], ''), ('actress', '왜 이래? 더 이상 안 볼 사람처럼.', "Why are you acting like this? Like people who won't meet anymore.", [(853, '왜 이래 더 이상 안 볼 사람처럼')], ''), ('joonmo', '아니죠, 자주 봬야죠.', 'No, of course we should see you often.', [(855, '아니죠')], 'Uses standard spelling 봬야죠 for caption 뵈야죠.'), ('joonmo', '열심히 해주셔서 감사합니다.', 'Thank you for giving it your all.', [(857, '열심히 해주셔서 감사합니다')], ''), ('actress', '앞으로도 걱정 마. 내가 더 열심히 한다고.', "Don't worry going forward either. I told you I will work even harder.", [(858, '앞으로도 걱정 마'), (858, '내가 더 열심히 한다고')], '')]

WALK = [(0, None, "'There is no word yet.'"), (1, None, "'Will everyone come?'"), (2, None, "'Ms. Youn Yuh-jung, please sit here.'"), (3, None, "'Hello.'"), (4, None, "'Teacher, let me pour you a glass.'"), (5, None, "'I took this show because of Producer Ra.'"), (6, None, "'Of course, I know.'"), (7, None, "'Because we heard you love the cake from this shop.'"), (8, None, "'Even by lunchtime, this shop sells out of cake.'"), (9, None, "'Teacher, thank you so much for all your hard work up to now.'"), (10, None, "'Why are you acting like this? Like people who won't meet anymore.'"), (11, None, "'No, of course we should see you often.'"), (12, None, "'Thank you for giving it your all.'"), (13, None, "'Don't worry going forward either. I told you I will work even harder.'")]
